'use strict';
const CACHE='zombie-zero-shell-v1';
const FILES=['./','./index.html','./style.css','./game.js','./app.js','./zombie-balls-bi.png','./manifest.webmanifest','./icons/icon-192.png','./icons/icon-512.png'];
self.addEventListener('install',event=>event.waitUntil(caches.open(CACHE).then(cache=>cache.addAll(FILES))));
self.addEventListener('activate',event=>event.waitUntil(caches.keys().then(keys=>Promise.all(keys.filter(k=>k.startsWith('zombie-zero-shell-')&&k!==CACHE).map(k=>caches.delete(k)))).then(()=>self.clients.claim())));
self.addEventListener('fetch',event=>{const u=new URL(event.request.url);if(event.request.method!=='GET'||u.origin!==self.location.origin)return;const known=FILES.some(p=>new URL(p,self.registration.scope).pathname===u.pathname);if(!known&&event.request.mode!=='navigate')return;event.respondWith(fetch(event.request).then(response=>{if(response.ok&&!response.redirected){const copy=response.clone();event.waitUntil(caches.open(CACHE).then(c=>c.put(event.request,copy)))}return response}).catch(async()=>{const cache=await caches.open(CACHE),hit=await cache.match(event.request);if(hit)return hit;if(event.request.mode==='navigate')return(await cache.match('./'))||Response.error();return Response.error()}))});
